CustomField.formula:
IF( Contains(DL_Category__c , 'Sub-Saharan Africa')
	,'Sub-Saharan Africa'
	, IF(
			 Contains(DL_Category__c , 'North America')
			 , 'North America'
			 , IF( Contains(DL_Category__c , 'Middle East/North Africa')
					,'Middle East/North Africa'
					,  IF( Contains(DL_Category__c , 'Latin America')
							,'Latin America'
							,  IF( Contains(DL_Category__c , 'Japan')
									,'Japan'
									, IF( Contains(DL_Category__c , 'Global Strategy')
										,'Global Strategy'
										, IF( Contains(DL_Category__c , 'Global Macro')
											,'Global Macro'
												, IF( Contains(DL_Category__c , 'Geo-Technology')
													,'Geo-Technology'
													,  IF( Contains(DL_Category__c , 'Europe')
														,'Europe'
														, IF( Contains(DL_Category__c , 'Eurasia')
															,'Eurasia'
															, IF( Contains(DL_Category__c , 'Energy, Climate & Resources')
																,'Energy, Climate & Resources'
																, IF( Contains(DL_Category__c , 'Data & Analytics')
																	,'Data & Analytics'
																	, IF( Contains(DL_Category__c , 'Asia')
																	,'Asia'
																	, DL_Category__c
																	)
																)
															)
														)
													)
											)
										)
									)
								)
						)
				)

	)
)
